<script setup lang="ts">import {useStudies} from '../stores/studies';import {useTask} from '../hooks/useTask';import ErrorNotice from './common/ErrorNotice.vue';const study=useStudies(),{error,perform}=useTask();</script><template><div><label class="study-select">研究册<select aria-label="选择研究" :value="study.selected" @change="perform(()=>study.select(Number(($event.target as HTMLSelectElement).value)))"><option v-for="s in study.items" :key="s.id" :value="s.id">{{s.code}} · {{s.name}}</option></select></label><ErrorNotice :error="error"/></div></template>